  task(row) { return row && { id:row.id,projectId:row.project_id,datasetId:row.dataset_id,displayName:row.display_name,description:row.description,status:row.status,activeAttemptId:row.active_attempt_id,publishedModelId:row.published_model_id,metadata:json(row.metadata_json),createdBy:row.created_by,createdAt:row.created_at,updatedAt:row.updated_at,archivedAt:row.archived_at }; }
  createTask(input) { const project=this.getProject(input.projectId),dataset=this.getDataset(input.datasetId);if(!project||project.status!=='active'||!dataset||dataset.status!=='finalized'||dataset.projectId!==project.id)throw Object.assign(new Error('task project and finalized dataset must match'),{code:'invalid_project_or_dataset'});const id=input.id||crypto.randomUUID(),t=now();this.database.prepare(`INSERT INTO processing_tasks(id,project_id,dataset_id,display_name,description,status,metadata_json,created_by,created_at,updated_at) VALUES (?,?,?,?,?,'draft',?,?,?,?)`).run(id,input.projectId,input.datasetId,bounded(input.displayName),bounded(input.description,4000)||null,JSON.stringify(input.metadata||{}),input.createdBy||null,t,t);return this.getTask(id); }
  getTask(id) { return this.task(this.database.prepare('SELECT * FROM processing_tasks WHERE id=?').get(id)); }
  listTasksPage({projectId=null,limit=50,cursor=null}={}) { const n=pageLimit(limit),c=decodeCursor(cursor);let rows;if(projectId&&c)rows=this.database.prepare('SELECT * FROM processing_tasks WHERE project_id=? AND (created_at<? OR (created_at=? AND id<?)) ORDER BY created_at DESC,id DESC LIMIT ?').all(projectId,c.createdAt,c.createdAt,c.id,n+1);else if(projectId)rows=this.database.prepare('SELECT * FROM processing_tasks WHERE project_id=? ORDER BY created_at DESC,id DESC LIMIT ?').all(projectId,n+1);else if(c)rows=this.database.prepare('SELECT * FROM processing_tasks WHERE created_at<? OR (created_at=? AND id<?) ORDER BY created_at DESC,id DESC LIMIT ?').all(c.createdAt,c.createdAt,c.id,n+1);else rows=this.database.prepare('SELECT * FROM processing_tasks ORDER BY created_at DESC,id DESC LIMIT ?').all(n+1);const more=rows.length>n,items=rows.slice(0,n),latest=new Map();if(items.length){const attempts=this.database.prepare(`SELECT * FROM processing_attempts WHERE task_id IN (${items.map(()=>'?').join(',')}) ORDER BY task_id,attempt_number DESC`).all(...items.map((r)=>r.id));for(const row of attempts)if(!latest.has(row.task_id))latest.set(row.task_id,this.attempt(row));}return{items:items.map((r)=>({...this.task(r),latestAttempt:latest.get(r.id)||null})),nextCursor:more?encodeCursor(items.at(-1)):null}; }
