  attempt(row) { return row && { id:row.id,taskId:row.task_id,attemptNumber:row.attempt_number,providerId:row.provider_id,providerTaskId:row.provider_task_id,presetId:row.preset_id,options:json(row.options_json),capabilityFingerprint:row.capability_fingerprint,status:row.status,progress:row.progress,providerOutputCursor:row.provider_output_cursor,errorCode:row.error_code,errorMessage:row.error_message,resultModelId:row.result_model_id,resultModelVersionId:row.result_model_version_id,createdBy:row.created_by,createdAt:row.created_at,updatedAt:row.updated_at,startedAt:row.started_at,upstreamCompletedAt:row.upstream_completed_at,ingestedAt:row.ingested_at,completedAt:row.completed_at }; }
  createAttempt(input) {
    return this.transaction(()=>{ const task=this.getTask(input.taskId); if(!task||task.status==='archived') throw new Error('task is not processable'); const dataset=this.getDataset(task.datasetId),project=this.getProject(task.projectId);if(!dataset||dataset.status!=='finalized'||dataset.projectId!==task.projectId||!project||project.status!=='active')throw new Error('dataset and project must be active and finalized');const active=task.activeAttemptId&&this.getAttempt(task.activeAttemptId);if(active&&!['failed','cancelled','published'].includes(active.status))throw Object.assign(new Error('task already has an active attempt'),{code:'attempt_in_progress'});
      const n=this.database.prepare('SELECT COALESCE(MAX(attempt_number),0)+1 AS n FROM processing_attempts WHERE task_id=?').get(task.id).n;
      const id=crypto.randomUUID(),t=now(); this.database.prepare(`INSERT INTO processing_attempts(id,task_id,attempt_number,provider_id,provider_task_id,preset_id,options_json,capability_fingerprint,status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,'pending',?,?,?)`).run(id,task.id,n,input.providerId,input.providerTaskId||crypto.randomUUID(),input.presetId||null,JSON.stringify(input.options||{}),input.capabilityFingerprint||null,input.createdBy||null,t,t);
      const markCount=Number(this.database.prepare('SELECT COUNT(*) count FROM gcp_image_correspondences WHERE task_id=?').get(task.id).count);
      if(markCount>100000)throw Object.assign(new Error('task has too many GCP image correspondences'),{code:'too_many_gcp_correspondences'});
      const marks=this.database.prepare(`SELECT points.longitude,points.latitude,points.elevation_m elevationM,
        marks.pixel_x pixelX,marks.pixel_y pixelY,files.relative_path relativePath
        FROM gcp_image_correspondences marks
        JOIN gcp_points points ON points.id=marks.gcp_point_id
        JOIN dataset_files files ON files.id=marks.dataset_file_id
        WHERE marks.task_id=? ORDER BY points.external_id,files.relative_path,marks.id`).all(task.id);
      const gcpList=odmGcpList(marks);
      if(gcpList&&Buffer.byteLength(gcpList)>16*1024*1024)throw Object.assign(new Error('generated ODM GCP input is too large'),{code:'gcp_snapshot_too_large'});
      if(gcpList)this.database.prepare(`INSERT INTO processing_attempt_gcp_snapshots(attempt_id,sha256,content_text,correspondence_count,created_at)
        VALUES (?,?,?,?,?)`).run(id,crypto.createHash('sha256').update(gcpList).digest('hex'),gcpList,marks.length,t);
      this.database.prepare(`INSERT INTO processing_jobs(id,attempt_id,job_type,status,available_at,created_at,updated_at) VALUES (?,?,'submit','pending',?,?,?)`).run(crypto.randomUUID(),id,t,t,t);
      this.database.prepare("UPDATE processing_tasks SET active_attempt_id=?,status='queued',updated_at=? WHERE id=?").run(id,t,task.id); return this.getAttempt(id); });
  }
  getAttempt(id) { return this.attempt(this.database.prepare('SELECT * FROM processing_attempts WHERE id=?').get(id)); }
  getAttemptGcpSnapshot(id){const row=this.database.prepare('SELECT * FROM processing_attempt_gcp_snapshots WHERE attempt_id=?').get(id);return row?{attemptId:row.attempt_id,sha256:row.sha256,content:row.content_text,correspondenceCount:Number(row.correspondence_count),createdAt:row.created_at}:null;}
